//! [`FullEq`] trait.
//!
//! A stricter version of [`ContentEq`], for comparing ASTs in tests.
//!
//! Impls for AST types are generated by `oxc_ast_tools`, in `generated/derive_full_eq.rs`.
//! Impls for container types are here.
//!
//! [`ContentEq`]: oxc::span::ContentEq

use std::cell::Cell;

use oxc::allocator::{ArenaBox, ArenaVec};

/// Compare every field of an AST node except `node_id`, recursively.
///
/// Unlike [`ContentEq`], compares spans, semantic IDs, and fields marked `#[content_eq(skip)]`
/// e.g. `raw`, and `Program`'s `source_text` and `comments`.
///
/// Node IDs are not compared.
///
/// [`ContentEq`]: oxc::span::ContentEq
pub trait FullEq {
    /// Get if `self` and `other` are equal in every field except `node_id`.
    fn full_eq(&self, other: &Self) -> bool;
}

impl<T: FullEq> FullEq for Option<T> {
    /// Get if both are `None`, or both are `Some` with values which are [`FullEq`].
    #[inline]
    fn full_eq(&self, other: &Self) -> bool {
        match (self, other) {
            (Some(a), Some(b)) => a.full_eq(b),
            (None, None) => true,
            _ => false,
        }
    }
}

impl<T: FullEq> FullEq for ArenaBox<'_, T> {
    /// Compare the boxed values.
    #[inline]
    fn full_eq(&self, other: &Self) -> bool {
        T::full_eq(self, other)
    }
}

impl<T: FullEq> FullEq for ArenaVec<'_, T> {
    /// Get if both have the same length, and every pair of elements is [`FullEq`].
    #[inline]
    fn full_eq(&self, other: &Self) -> bool {
        self.len() == other.len() && self.iter().zip(other).all(|(a, b)| a.full_eq(b))
    }
}

impl<T: Copy + FullEq> FullEq for Cell<T> {
    /// Compare the values in the cells.
    #[inline]
    fn full_eq(&self, other: &Self) -> bool {
        self.get().full_eq(&other.get())
    }
}
